import {defaults,normaliseKit,describeKit,priceKit,builderURL,lesPaul} from '../../les-paul-kits/config.mjs';
export function recommend(answers={}){
 const reasons=[],checks=[];
 if(answers.guitar!=='les-paul')return {supported:false,title:'Let’s confirm the right harness first.',message:'The current builder is for Les Paul style two-volume, two-tone layouts. Other kits are in development. Confirm your guitar model and control layout before choosing a harness.',route:'/wiring-kits/#collection'};
 if(answers.pickups==='active'||answers.pickups==='other'||answers.pickups==='unsure')return {supported:false,title:'Check your pickup requirements first.',message:'This kit uses 500kΩ pots for a passive circuit. Confirm the pickup type and manufacturer’s control requirements before selecting it, especially with active electronics.',route:'/components/'};
 if(answers.scope!=='full')return {supported:false,title:'You may only need individual components.',message:answers.scope==='partial'?'A complete four-pot harness may replace more than you need. Explore individual parts, or return to the questions if you decide to replace the complete passive harness.':'Check which controls need replacing first. The Les Paul kit is a complete four-pot harness, not a partial repair kit.',route:'/components/'};
 const config={...defaults,wiring:'modern',model:'Les Paul style'};
 if(answers.feel==='interactive'){config.wiring='50s';reasons.push('50s wiring suits your interest in using volume and tone together. Their settings interact; no treble bleed is added to this kit.');}
 else {reasons.push('Modern wiring is a straightforward starting point for separate volume and tone adjustment.');if(answers.volume==='often'&&answers.clarity==='yes'){config.bleed='prs';reasons.push('The PRS-style capacitor pair is a starting point for keeping more high-frequency content as you lower the volume. Its effect depends on the pickups, controls and cable.');}else reasons.push('No treble bleed is added because you have not asked for extra high-frequency retention while turning down the volume.');}
 config.shaft=answers.shaft==='long'?'long':'short';
 if(answers.shaft==='unsure'){checks.push('Short shaft is a provisional selection, not a fitment recommendation. Measure the required mounting depth before assembly.');config.model+=' / shaft fitment unconfirmed';}else reasons.push(lesPaul.shaft[config.shaft].label+' follows the mounting depth you selected.');
 checks.push('Check mounting-hole diameter, knob fit and cavity clearance. A guitar’s model name alone does not guarantee compatibility.');
 config.matching=answers.matching==='yes'?'precision':'standard';reasons.push(config.matching==='precision'?lesPaul.matching.precision.description:'Standard Tested includes an individual electrical check of every pot, with no matching upgrade.');
 if(answers.hardware==='replace'){config.jack='pureTone';config.selector='switchcraft';reasons.push('A Pure Tone jack and Switchcraft toggle replace both pieces of hardware, as requested. Confirm physical fit before assembly.');}else reasons.push('No jack or selector is included, so you can retain suitable existing hardware or choose replacements in the builder.');
 reasons.push('Two 0.022µF 715P capacitors are the standard starting specification. You can choose a different capacitance or pair in the builder.');
 const configuration=normaliseKit(config);return {supported:true,title:'Your recommended kit',configuration,specification:describeKit(configuration),pricing:priceKit(configuration),reasons,checks,url:builderURL(configuration)};
}
